//! v0.14 M3: every case of the Buzz 1.0 client-contract fixtures
//! (tests/fixtures/buzz-app/README.md). Expected values are the fixtures'
//! literals; nothing here is generated by the code under test.
use std::collections::HashMap;

use bzz::protocol::{
    identity_names::{self, Fact},
    mention_rules::{self, Choice, Presence},
};
use serde_json::Value;

fn fixture(name: &str) -> Value {
    let path = format!(
        "{}/tests/fixtures/buzz-app/{name}",
        env!("CARGO_MANIFEST_DIR")
    );
    serde_json::from_str(&std::fs::read_to_string(path).unwrap()).unwrap()
}

fn text(value: &Value) -> String {
    value.as_str().unwrap_or_default().to_owned()
}

fn keys(value: &Value) -> Vec<String> {
    value
        .as_array()
        .map(|values| values.iter().map(text).collect())
        .unwrap_or_default()
}

/// Run every case, collect failures, and report them all at once.
fn check(section: &str, cases: &Value, mut run: impl FnMut(&Value) -> Result<(), String>) -> usize {
    let cases = cases
        .as_array()
        .unwrap_or_else(|| panic!("{section} has cases"));
    let failures = cases
        .iter()
        .filter_map(|case| {
            run(case)
                .err()
                .map(|why| format!("{section}/{}: {why}", text(&case["name"])))
        })
        .collect::<Vec<_>>();
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
    cases.len()
}

#[test]
fn identity_names_v1_fixtures() {
    let fixture = fixture("identity-names.fixtures.json");
    assert_eq!(fixture["version"], 1);
    let count = check("identity-names", &fixture["cases"], |case| {
        let facts = case["identities"]
            .as_array()
            .unwrap()
            .iter()
            .map(|row| Fact {
                pubkey: text(&row["pubkey"]),
                name: text(&row["name"]),
                is_agent: row["isAgent"].as_bool().unwrap_or(false),
                owner_pubkey: row["ownerPubkey"].as_str().map(str::to_owned),
            })
            .collect::<Vec<_>>();
        let candidates = case.get("candidates").map(keys);
        let got = identity_names::resolve(&facts, case["viewer"].as_str(), candidates.as_deref());
        let expected = case["expected"].as_object().unwrap();
        let mut problems = Vec::new();
        if got.len() != expected.len() {
            problems.push(format!("{} keys, expected {}", got.len(), expected.len()));
        }
        for (key, want) in expected {
            let want_name = text(&want["name"]);
            let want_qualifier = want["qualifier"].as_str().map(str::to_owned);
            match got.get(key) {
                Some(resolved)
                    if resolved.name == want_name && resolved.qualifier == want_qualifier => {}
                other => problems.push(format!(
                    "{key}: got {other:?}, expected {want_name:?} / {want_qualifier:?}"
                )),
            }
        }
        if problems.is_empty() {
            Ok(())
        } else {
            Err(problems.join("; "))
        }
    });
    assert_eq!(count, 31);
}

fn choice(value: &Value) -> Choice {
    let name = text(&value["name"]);
    Choice {
        pubkey: text(&value["pubkey"]),
        label: value["label"]
            .as_str()
            .map_or_else(|| name.clone(), str::to_owned),
        qualifier: value["qualifier"].as_str().map(str::to_owned),
        aliases: value
            .get("aliases")
            .map_or_else(|| vec![name.clone()], keys),
        member: value["member"].as_bool().unwrap_or(false),
        elsewhere: value["elsewhere"].as_str().map(str::to_owned),
        agent: value["agent"].as_bool().unwrap_or(false),
        owned: value["owned"].as_bool().unwrap_or(false),
        managed: value["managed"].as_bool().unwrap_or(false),
        name,
    }
}

fn choices(case: &Value) -> Vec<Choice> {
    case["choices"]
        .as_array()
        .unwrap()
        .iter()
        .map(choice)
        .collect()
}

#[test]
fn mention_rules_v3_fixtures() {
    let fixture = fixture("mention-rules.fixtures.json");
    assert_eq!(fixture["version"], 3);
    let mut total = 0;

    total += check("matching", &fixture["matching"], |case| {
        let got = mention_rules::match_tier(&text(&case["label"]), &text(&case["query"]));
        let want = case["expected"].as_u64().map(|tier| tier as u32);
        if got == want {
            Ok(())
        } else {
            Err(format!("got {got:?}, expected {want:?}"))
        }
    });

    total += check("ranking", &fixture["ranking"], |case| {
        let choices = choices(case);
        let history = case["history"]
            .as_object()
            .map(|map| {
                map.iter()
                    .map(|(key, value)| (key.clone(), value.as_u64().unwrap_or(0)))
                    .collect::<HashMap<_, _>>()
            })
            .unwrap_or_default();
        let presence = case["presence"].as_object().cloned().unwrap_or_default();
        let order =
            mention_rules::rank(
                &choices,
                &text(&case["query"]),
                &history,
                |key| match presence.get(key).and_then(Value::as_str) {
                    Some("online") => Presence::Online,
                    Some("away") => Presence::Away,
                    _ => Presence::Unknown,
                },
            );
        let got = order
            .into_iter()
            .map(|index| choices[index].pubkey.clone())
            .collect::<Vec<_>>();
        let want = keys(&case["expected"]);
        if got == want {
            Ok(())
        } else {
            Err(format!("got {got:?}, expected {want:?}"))
        }
    });

    total += check("space", &fixture["space"], |case| {
        let got = mention_rules::exact_mention(&choices(case), &text(&case["query"]), |_| true);
        let want = case["expected"].as_str().map(str::to_owned);
        if got == want {
            Ok(())
        } else {
            Err(format!("got {got:?}, expected {want:?}"))
        }
    });

    total += check("query", &fixture["query"], |case| {
        let body = text(&case["text"]);
        // Fixture carets are UTF-16 indexes; out-of-range ones stay invalid.
        let caret = case["caret"].as_i64().unwrap();
        let got = usize::try_from(caret)
            .ok()
            .and_then(|caret| {
                let units = body.encode_utf16().count();
                (caret <= units).then(|| {
                    let mut seen = 0;
                    body.char_indices()
                        .find(|(_, c)| {
                            let here = seen >= caret;
                            seen += c.len_utf16();
                            here
                        })
                        .map_or(body.len(), |(index, _)| index)
                })
            })
            .and_then(|caret| mention_rules::mention_query(&body, caret))
            .map(|query| (query.start, query.end, query.query));
        let want = case["expected"].as_object().map(|want| {
            (
                want["start"].as_u64().unwrap() as usize,
                want["end"].as_u64().unwrap() as usize,
                text(&want["query"]),
            )
        });
        if got == want {
            Ok(())
        } else {
            Err(format!("got {got:?}, expected {want:?}"))
        }
    });

    total += check("admission", &fixture["admission"], |case| {
        let got = mention_rules::admitted(&text(&case["query"]), &keys(&case["names"]));
        let want = case["expected"].as_bool().unwrap();
        if got == want {
            Ok(())
        } else {
            Err(format!("got {got}, expected {want}"))
        }
    });

    total += check("tags.write", &fixture["tags"]["write"], |case| {
        let sender = "f".repeat(64);
        let got = mention_rules::write_tags(
            &sender,
            &keys(&case["members"]),
            &keys(&case["recipients"]),
            &keys(&case["references"]),
        );
        let want = &case["expected"];
        match (got, want["error"].as_str()) {
            (Err(error), Some(expected)) if error.as_str() == expected => Ok(()),
            (Ok(tags), None) => {
                let want = want["tags"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .map(keys)
                    .collect::<Vec<_>>();
                if tags == want {
                    Ok(())
                } else {
                    Err(format!("got {tags:?}, expected {want:?}"))
                }
            }
            (got, expected) => Err(format!("got {got:?}, expected {expected:?}")),
        }
    });

    total += check("tags.read", &fixture["tags"]["read"], |case| {
        let tags = case["tags"]
            .as_array()
            .unwrap()
            .iter()
            .map(keys)
            .collect::<Vec<_>>();
        let got = mention_rules::read_tags(&tags);
        let want = (
            keys(&case["expected"]["mentions"]),
            keys(&case["expected"]["references"]),
        );
        if got == want {
            Ok(())
        } else {
            Err(format!("got {got:?}, expected {want:?}"))
        }
    });

    assert_eq!(total, 23 + 35 + 23 + 12 + 9 + 7 + 6);
}
